"""Implementation of the ``audit-orders`` subcommand.

The audit reads an order CSV and reports field-level validation errors and
cross-row duplicate/conflict findings as JSON Lines.  Only the Python standard
library is used.
"""

from __future__ import annotations

import csv
import hashlib
import io
import json
import os
import re
from collections import defaultdict
from datetime import datetime
from typing import BinaryIO

# Logical field names and the order in which fields of a single row are
# validated (deterministic order for multiple findings on one row).
FIELDS = ("order_id", "sku", "qty", "status", "updated_at")

# Strict ISO 8601, second precision, with a mandatory time zone designator.
# Fractional seconds, minute-only offsets, compact/basic formats and week or
# ordinal dates are intentionally rejected.
_ISO_RE = re.compile(
    r"^(\d{4})-(\d{2})-(\d{2})[Tt ](\d{2}):(\d{2}):(\d{2})(Z|[+-]\d{2}:\d{2})$"
)
_QTY_RE = re.compile(r"^[1-9][0-9]*$")

BOM = "﻿"


class AuditError(Exception):
    """A fatal input error (exit status 2)."""

    def __init__(self, message: str, *, filename: str | None = None):
        super().__init__(message)
        self.message = message
        self.filename = filename


def parse_schema(raw: str, source: str) -> dict[str, list[str]]:
    """Validate the UTF-8 JSON schema text and resolve column candidates.

    ``source`` labels the schema argument in error messages (``"--schema"``).
    """
    try:
        obj = json.loads(raw)
    except (json.JSONDecodeError, RecursionError) as exc:
        raise AuditError(f"{source}: schema is not valid JSON: {exc}", filename=source)
    if not isinstance(obj, dict):
        raise AuditError(f"{source}: schema must be a JSON object", filename=source)

    schema: dict[str, list[str]] = {}
    for field in FIELDS:
        if field not in obj:
            raise AuditError(
                f"{source}: schema is missing required key {field!r}", filename=source
            )
        candidates = obj[field]
        if not isinstance(candidates, list) or not candidates:
            raise AuditError(
                f"{source}: value for {field!r} must be a non-empty array",
                filename=source,
            )
        for cand in candidates:
            if not isinstance(cand, str) or not cand:
                raise AuditError(
                    f"{source}: candidate column names for {field!r} must be "
                    "non-empty strings",
                    filename=source,
                )
        schema[field] = candidates

    if len(obj) != len(FIELDS):
        extra = sorted(set(obj) - set(FIELDS))
        raise AuditError(
            f"{source}: schema contains unsupported keys: {', '.join(extra)}",
            filename=source,
        )

    return schema


def resolve_columns(
    schema: dict[str, list[str]], header: list[str], source: str
) -> dict[str, int]:
    """Map each logical field to exactly one header index.

    Each field must match exactly one column among its candidates and the
    selected columns must be pairwise distinct.
    """
    columns: dict[str, int] = {}
    for field in FIELDS:
        hits = [i for i, name in enumerate(header) if name in schema[field]]
        if not hits:
            raise AuditError(
                f"{source}: no header column matches candidates {schema[field]!r} "
                f"for field {field!r}",
                filename=source,
            )
        if len(hits) > 1:
            names = sorted(header[i] for i in hits)
            raise AuditError(
                f"{source}: multiple header columns match field {field!r}: "
                f"{', '.join(names)}",
                filename=source,
            )
        columns[field] = hits[0]

    seen: dict[int, str] = {}
    for field in FIELDS:
        idx = columns[field]
        if idx in seen:
            raise AuditError(
                f"{source}: fields {seen[idx]!r} and {field!r} both select "
                f"column {header[idx]!r}; selected columns must be distinct",
                filename=source,
            )
        seen[idx] = field
    return columns


def _valid_iso8601_seconds(text: str) -> bool:
    match = _ISO_RE.match(text)
    if match is None:
        return False
    year, month, day, hour, minute, second = (int(g) for g in match.groups()[:6])
    try:
        # Calendar validation; tzinfo supplies the mandatory zone.
        datetime(year, month, day, hour, minute, second)
    except ValueError:
        return False
    return True


def _validate_field(field: str, raw_value: str) -> tuple[bool, str]:
    """Return ``(valid, value)``; ``value`` is the trimmed text."""
    value = raw_value.strip()
    if field in ("order_id", "sku"):
        return bool(value), value
    if field == "qty":
        return bool(_QTY_RE.match(value)), value
    if field == "status":
        return value in ("open", "cancelled"), value
    if field == "updated_at":
        return bool(value) and _valid_iso8601_seconds(value), value
    return False, value  # pragma: no cover - defensive, FIELDS is fixed


def audit(data: bytes, schema_text: str, input_name: str) -> tuple[list[str], int]:
    """Run the audit; return ``(jsonl_lines, data_row_count)``.

    Raises :class:`AuditError` for fatal schema, encoding, CSV or header
    errors.
    """
    schema = parse_schema(schema_text, "--schema")

    # BOM is allowed on the INPUT file; the schema string is validated as
    # plain UTF-8 JSON by the caller (a BOM there is a JSON error).
    text = None
    try:
        text = data.decode("utf-8-sig")
    except UnicodeDecodeError as exc:
        raise AuditError(
            f"{input_name}: input is not valid UTF-8: {exc.reason} at byte "
            f"{exc.start}",
            filename=input_name,
        )

    try:
        rows = list(csv.reader(io.StringIO(text, newline=""), strict=True))
    except csv.Error as exc:
        # With strict=True this catches malformed quoting / unterminated rows.
        raise AuditError(f"{input_name}: malformed CSV: {exc}", filename=input_name)

    if not rows:
        raise AuditError(f"{input_name}: CSV is empty (no header)", filename=input_name)

    header = rows[0]
    if not header or (len(header) == 1 and header[0] == ""):
        raise AuditError(f"{input_name}: CSV header must not be empty", filename=input_name)
    if any(name == "" for name in header):
        raise AuditError(
            f"{input_name}: CSV header must not contain an empty column name",
            filename=input_name,
        )
    if len(set(header)) != len(header):
        dupes = sorted({name for name in header if header.count(name) > 1})
        raise AuditError(
            f"{input_name}: duplicate header column names: {', '.join(dupes)}",
            filename=input_name,
        )

    columns = resolve_columns(schema, header, input_name)

    findings: list[tuple] = []
    groups: dict[tuple[str, str], list[tuple]] = []  # type: ignore[assignment]
    groups = defaultdict(list)
    data_row_count = 0

    for raw in rows[1:]:
        # Blank physical lines parse to [] and are not data rows. A line of
        # only whitespace yields [" "]; treat that as blank too.
        if not raw or all(cell.strip() == "" for cell in raw):
            continue
        data_row_count += 1
        record_no = data_row_count + 1  # header is record 1

        if len(raw) != len(header):
            findings.append(
                ["invalid", record_no, "row", f"{len(raw)} columns, expected {len(header)}"]
            )
            continue

        values: dict[str, str] = {}
        row_errors: list[tuple] = []
        for field in FIELDS:
            ok, value = _validate_field(field, raw[columns[field]])
            values[field] = value
            if not ok:
                row_errors.append(
                    ["invalid", record_no, field, raw[columns[field]]]
                )
        if row_errors:
            findings.extend(row_errors)
            continue

        groups[(values["order_id"], values["sku"])].append(
            (
                record_no,
                int(values["qty"]),
                values["status"],
                values["updated_at"],
            )
        )

    for (oid, sku), members in groups.items():
        if len(members) < 2:
            continue
        record_numbers = sorted(m[0] for m in members)
        kind = "duplicate"
        first = members[0]
        for member in members[1:]:
            if member[1:4] != first[1:4]:
                kind = "conflict"
                break
        findings.append([kind, [oid, sku], record_numbers])

    # Sort findings by (smallest involved record number, kind, field).
    type_rank = {"invalid": 0, "duplicate": 1, "conflict": 2}

    def sort_key(item: tuple) -> tuple:
        if item[0] == "invalid":
            return (item[1], type_rank[item[0]], item[2], json.dumps(item[3], ensure_ascii=False))
        return (item[2][0], type_rank[item[0]], "", json.dumps(item, ensure_ascii=False))

    findings.sort(key=sort_key)

    digest = hashlib.sha256(data).hexdigest()
    findings.append(["summary", data_row_count, len(findings), digest])

    lines = [json.dumps(item, ensure_ascii=False, separators=(",", ":")) for item in findings]
    return lines, data_row_count


def run_audit(
    schema_text: str,
    input_path: str,
    output_path: str | None = None,
    stdout: BinaryIO | None = None,
) -> int:
    """File-level wrapper: reads INPUT, writes the report, returns exit code.

    Fatal errors raise :class:`AuditError`; the caller formats stderr.
    """
    try:
        with open(input_path, "rb") as fh:
            data = fh.read()
    except OSError as exc:
        raise AuditError(f"cannot read input file: {exc}", filename=input_path)

    lines, _ = audit(data, schema_text, input_path)
    payload = ("\n".join(lines) + "\n").encode("utf-8")

    if output_path is None:
        if stdout is None:  # pragma: no cover - always injected by main
            import sys

            stdout = sys.stdout.buffer
        stdout.write(payload)
        stdout.flush()
    else:
        _atomic_write(output_path, payload)

    return 1 if any(json.loads(line)[0] != "summary" for line in lines) else 0


def _atomic_write(path: str, payload: bytes) -> None:
    directory = os.path.dirname(os.path.abspath(path)) or "."
    tmp_path = None
    try:
        try:
            os.makedirs(directory, exist_ok=True)
        except OSError as exc:
            raise AuditError(f"cannot prepare output directory: {exc}", filename=path)

        import tempfile

        fd, tmp_path = tempfile.mkstemp(
            prefix=f".{os.path.basename(path)}.", suffix=".tmp", dir=directory
        )
        try:
            with os.fdopen(fd, "wb") as fh:
                fh.write(payload)
                fh.flush()
                os.fsync(fh.fileno())
            os.replace(tmp_path, path)
            tmp_path = None
        except OSError as exc:
            raise AuditError(f"cannot write output file: {exc}", filename=path)
    finally:
        if tmp_path is not None and os.path.exists(tmp_path):
            try:
                os.unlink(tmp_path)
            except OSError:
                pass

